diff --git a/test/ut/spec/component/tooltip/tooltip.test.ts b/test/ut/spec/component/tooltip/tooltip.test.ts
index e6a5228..4939e1f 100644
--- a/test/ut/spec/component/tooltip/tooltip.test.ts
+++ b/test/ut/spec/component/tooltip/tooltip.test.ts
@@ -199,4 +199,67 @@ describe('component/tooltip', function () {
             expect(tooltipEl.innerHTML.indexOf('color:#666') >= 0).toBe(true);
         });
     });
+
+    describe('setOption with notMerge', function () {
+
+        function makeOption(showDelay?: number) {
+            return {
+                tooltip: {
+                    showDelay: showDelay || 0
+                },
+                xAxis: {
+                    type: 'category',
+                    data: ['A', 'B']
+                },
+                yAxis: {},
+                series: [{
+                    type: 'bar',
+                    name: 'S1',
+                    data: [11, 22]
+                }]
+            };
+        }
+
+        it('should not throw when setOption with notMerge and showTip', function () {
+            expect(function () {
+                chart.setOption(makeOption(), true);
+                chart.setOption(makeOption(), true);
+                chart.dispatchAction({
+                    type: 'showTip',
+                    seriesIndex: 0,
+                    dataIndex: 0
+                });
+            }).not.toThrow();
+
+            // Position is still updated on the new tooltip layer.
+            const tooltipEl = getTooltipEl(chart);
+            expect(tooltipEl).not.toBeNull();
+            expect(tooltipEl.innerHTML === '').toBe(false);
+            expect(tooltipEl.style.left === '' && tooltipEl.style.top === '').toBe(false);
+        });
+
+        it('should not throw when the tooltip layer is disposed by notMerge before showing', function () {
+            jest.useFakeTimers();
+            try {
+                // `showDelay` defers `_showTooltipContent` (which updates the
+                // content size and position) to a timer. The tooltip layer that
+                // is captured by the timer is disposed by the `notMerge`
+                // `setOption` below.
+                chart.setOption(makeOption(100), true);
+                chart.dispatchAction({
+                    type: 'showTip',
+                    seriesIndex: 0,
+                    dataIndex: 0
+                });
+                chart.setOption(makeOption(100), true);
+
+                expect(function () {
+                    jest.advanceTimersByTime(500);
+                }).not.toThrow();
+            }
+            finally {
+                jest.useRealTimers();
+            }
+        });
+    });
 });

