 20	import { isString, indexOf, each, bind, isFunction, isArray, isDom, retrieve2 } from 'zrender/src/core/util';
 21	import { normalizeEvent } from 'zrender/src/core/event';
 22	import { transformLocalCoord } from 'zrender/src/core/dom';
 23	import env from 'zrender/src/core/env';
 24	import { convertToColorString, toCamelCase, normalizeCssArray } from '../../util/format';
 25	import type ExtensionAPI from '../../core/ExtensionAPI';
 26	import type { ZRenderType } from 'zrender/src/zrender';
 27	import type { TooltipOption } from './TooltipModel';
 28	import Model from '../../model/Model';
 29	import type { ZRRawEvent } from 'zrender/src/core/types';
 30	import type { ZRColor } from '../../util/types';
 31	import type CanvasPainter from 'zrender/src/canvas/Painter';
 32	import type SVGPainter from 'zrender/src/svg/Painter';
 33	import {
 34	    shouldTooltipConfine,
 35	    toCSSVendorPrefix,
 36	    getComputedStyle,
 37	    TRANSFORM_VENDOR,
 38	    TRANSITION_VENDOR
 39	} from './helper';
 40	import { getPaddingFromTooltipModel } from './tooltipMarkup';
 41	
 42	/* global document, window */
 43	
 44	const CSS_TRANSITION_VENDOR = toCSSVendorPrefix(TRANSITION_VENDOR, 'transition');
 45	const CSS_TRANSFORM_VENDOR = toCSSVendorPrefix(TRANSFORM_VENDOR, 'transform');
 46	
 47	// eslint-disable-next-line
 48	const gCssText = `position:absolute;display:block;border-style:solid;white-space:nowrap;z-index:9999999;${env.transform3dSupported ? 'will-change:transform;' : ''}`;
 49	
 50	function mirrorPos(pos: string): string {
 51	    pos = pos === 'left'
 52	        ? 'right'
 53	        : pos === 'right'
 54	        ? 'left'
 55	        : pos === 'top'
 56	        ? 'bottom'
 57	        : 'top';
 58	    return pos;
 59	}
 60	
 61	function assembleArrow(
 62	    tooltipModel: Model<TooltipOption>,
 63	    borderColor: ZRColor,
 64	    arrowPosition: TooltipOption['position']
 65	) {
 66	    if (!isString(arrowPosition) || arrowPosition === 'inside') {
 67	        return '';
 68	    }
 69	
 70	    const backgroundColor = tooltipModel.get('backgroundColor');
 71	    const borderWidth = tooltipModel.get('borderWidth');
 72	
 73	    borderColor = convertToColorString(borderColor);
 74	    const arrowPos = mirrorPos(arrowPosition);
 75	    const arrowSize = Math.max(Math.round(borderWidth) * 1.5, 6);
 76	    let positionStyle = '';
 77	    let transformStyle = CSS_TRANSFORM_VENDOR + ':';
 78	    let rotateDeg;
 79	    if (indexOf(['left', 'right'], arrowPos) > -1) {
 80	        positionStyle += 'top:50%';
 81	        transformStyle += `translateY(-50%) rotate(${rotateDeg = arrowPos === 'left' ? -225 : -45}deg)`;
 82	    }
 83	    else {
 84	        positionStyle += 'left:50%';
 85	        transformStyle += `translateX(-50%) rotate(${rotateDeg = arrowPos === 'top' ? 225 : 45}deg)`;
 86	    }
 87	    const rotateRadian = rotateDeg * Math.PI / 180;
 88	    const arrowWH = arrowSize + borderWidth;
 89	    const rotatedWH = arrowWH * Math.abs(Math.cos(rotateRadian)) + arrowWH * Math.abs(Math.sin(rotateRadian));
 90	    const arrowOffset = Math.round(((rotatedWH - Math.SQRT2 * borderWidth) / 2
 91	        + Math.SQRT2 * borderWidth - (rotatedWH - arrowWH) / 2) * 100) / 100;
 92	    positionStyle += `;${arrowPos}:-${arrowOffset}px`;
 93	
 94	    const borderStyle = `${borderColor} solid ${borderWidth}px;`;
 95	    const styleCss = [
 96	        `position:absolute;width:${arrowSize}px;height:${arrowSize}px;z-index:-1;`,
 97	        `${positionStyle};${transformStyle};`,
 98	        `border-bottom:${borderStyle}`,
 99	        `border-right:${borderStyle}`,
100	        `background-color:${backgroundColor};`
101	    ];
102	
103	    return `<div style="${styleCss.join('')}"></div>`;
104	}
105	
106	function assembleTransition(duration: number, onlyFade?: boolean): string {
107	    const transitionCurve = 'cubic-bezier(0.23,1,0.32,1)';
108	    let transitionOption = ` ${duration / 2}s ${transitionCurve}`;
109	    let transitionText = `opacity${transitionOption},visibility${transitionOption}`;
110	    if (!onlyFade) {
111	        transitionOption = ` ${duration}s ${transitionCurve}`;
112	        transitionText += env.transformSupported
113	            ? `,${CSS_TRANSFORM_VENDOR}${transitionOption}`
114	            : `,left${transitionOption},top${transitionOption}`;
115	    }
116	
117	    return CSS_TRANSITION_VENDOR + ':' + transitionText;
118	}
119	
120	function assembleTransform(x: number, y: number, toString?: boolean) {
121	    // If using float on style, the final width of the dom might
122	    // keep changing slightly while mouse move. So `toFixed(0)` them.
123	    const x0 = x.toFixed(0) + 'px';
124	    const y0 = y.toFixed(0) + 'px';
125	    // not support transform, use `left` and `top` instead.
126	    if (!env.transformSupported) {
127	        return toString
128	            ? `top:${y0};left:${x0};`
129	            : [['top', y0], ['left', x0]];
130	    }
131	    // support transform
132	    const is3d = env.transform3dSupported;
133	    const translate = `translate${is3d ? '3d' : ''}(${x0},${y0}${is3d ? ',0' : ''})`;
134	    return toString
135	        ? 'top:0;left:0;' + CSS_TRANSFORM_VENDOR + ':' + translate + ';'
136	        : [['top', 0], ['left', 0], [TRANSFORM_VENDOR, translate]];
137	}
138	
139	/**
140	 * @param {Object} textStyle
141	 * @return {string}
142	 * @inner
143	 */
144	function assembleFont(textStyleModel: Model<TooltipOption['textStyle']>): string {
145	    const cssText = [];
146	
147	    const fontSize = textStyleModel.get('fontSize');
148	    const color = textStyleModel.getTextColor();
149	
150	    color && cssText.push('color:' + color);
151	
152	    cssText.push('font:' + textStyleModel.getFont());
153	
154	    // @ts-ignore, leave it to the tooltip refactor.
155	    const lineHeight = retrieve2(textStyleModel.get('lineHeight'), Math.round(fontSize * 3 / 2));
156	    fontSize
157	        && cssText.push('line-height:' + lineHeight + 'px');
158	
159	    const shadowColor = textStyleModel.get('textShadowColor');
160	    const shadowBlur = textStyleModel.get('textShadowBlur') || 0;
161	    const shadowOffsetX = textStyleModel.get('textShadowOffsetX') || 0;
162	    const shadowOffsetY = textStyleModel.get('textShadowOffsetY') || 0;
163	    shadowColor && shadowBlur
164	        && cssText.push('text-shadow:' + shadowOffsetX + 'px ' + shadowOffsetY + 'px '
165	            + shadowBlur + 'px ' + shadowColor);
166	
167	    each(['decoration', 'align'] as const, function (name) {
168	        const val = textStyleModel.get(name);
169	        val && cssText.push('text-' + name + ':' + val);
170	    });
171	
172	    return cssText.join(';');
173	}
174	
175	function assembleCssText(tooltipModel: Model<TooltipOption>, enableTransition?: boolean, onlyFade?: boolean) {
176	    const cssText: string[] = [];
177	    const transitionDuration = tooltipModel.get('transitionDuration');
178	    const backgroundColor = tooltipModel.get('backgroundColor');
179	    const shadowBlur = tooltipModel.get('shadowBlur');
180	    const shadowColor = tooltipModel.get('shadowColor');
181	    const shadowOffsetX = tooltipModel.get('shadowOffsetX');
182	    const shadowOffsetY = tooltipModel.get('shadowOffsetY');
183	    const textStyleModel = tooltipModel.getModel('textStyle');
184	    const padding = getPaddingFromTooltipModel(tooltipModel, 'html');
185	    const boxShadow = `${shadowOffsetX}px ${shadowOffsetY}px ${shadowBlur}px ${shadowColor}`;
186	
187	    cssText.push('box-shadow:' + boxShadow);
188	    // Animation transition. Do not animate when transitionDuration is 0.
189	    enableTransition && transitionDuration && cssText.push(assembleTransition(transitionDuration, onlyFade));
190	
191	    if (backgroundColor) {
192	        cssText.push('background-color:' + backgroundColor);
193	    }
194	
195	    // Border style
196	    each(['width', 'color', 'radius'] as const, function (name) {
197	        const borderName = 'border-' + name;
198	        const camelCase = toCamelCase(borderName) as 'borderWidth' | 'borderColor' | 'borderRadius';
199	        const val = tooltipModel.get(camelCase);
200	        val != null
201	            && cssText.push(borderName + ':' + val + (name === 'color' ? '' : 'px'));
202	    });
203	
204	    // Text style
205	    cssText.push(assembleFont(textStyleModel));
206	
207	    // Padding
208	    if (padding != null) {
209	        cssText.push('padding:' + normalizeCssArray(padding).join('px ') + 'px');
210	    }
211	
212	    return cssText.join(';') + ';';
213	}
214	
215	// If not able to make, do not modify the input `out`.
216	function makeStyleCoord(
217	    out: number[],
218	    zr: ZRenderType,
219	    container: HTMLElement | null | undefined,
220	    zrX: number,
221	    zrY: number
222	) {
223	    const zrPainter = zr && zr.painter;
224	
225	    if (container) {
226	        const zrViewportRoot = zrPainter && zrPainter.getViewportRoot();
227	        if (zrViewportRoot) {
228	            // Some APPs might use scale on body, so we support CSS transform here.
229	            transformLocalCoord(out, zrViewportRoot, container, zrX, zrY);
230	        }
231	    }
232	    else {
233	        out[0] = zrX;
234	        out[1] = zrY;
235	        // xy should be based on canvas root. But tooltipContent is
236	        // the sibling of canvas root. So padding of ec container
237	        // should be considered here.
238	        const viewportRootOffset = zrPainter && (zrPainter as CanvasPainter | SVGPainter).getViewportRootOffset();
239	        if (viewportRootOffset) {
240	            out[0] += viewportRootOffset.offsetLeft;
241	            out[1] += viewportRootOffset.offsetTop;
242	        }
243	    }
244	
245	    out[2] = zr ? out[0] / zr.getWidth() : 0;
246	    out[3] = zr ? out[1] / zr.getHeight() : 0;
247	}
248	
249	interface TooltipContentOption {
250	    /**
251	     * Specify target container of the tooltip element.
252	     * Can either be an HTMLElement, CSS selector string, or a function that returns an HTMLElement.
253	     */
254	    appendTo: ((chartContainer: HTMLElement) => HTMLElement | undefined | null) | HTMLElement | string
255	}
256	
257	class TooltipHTMLContent {
258	
259	    el: HTMLDivElement;
260	
261	    private _api: ExtensionAPI;
262	    private _container: HTMLElement | undefined | null;
263	
264	    private _show: boolean = false;
265	
266	    private _styleCoord: [number, number, number, number] = [0, 0, 0, 0];
267	
268	    private _enterable = true;
269	    private _zr: ZRenderType;
270	
271	    private _alwaysShowContent: boolean = false;
272	    private _hideTimeout: number;
273	    /**
274	     * Hide delay time
275	     */
276	    private _hideDelay: number;
277	
278	    private _inContent: boolean;
279	    private _firstShow = true;
280	    private _longHide = true;
281	    /**
282	     * Record long-time hide
283	     */
284	    private _longHideTimeout: number;
285	
286	    constructor(
287	        api: ExtensionAPI,
288	        opt: TooltipContentOption
289	    ) {
290	        if (env.wxa) {
291	            return null;
292	        }
293	
294	        const el = document.createElement('div');
295	        // TODO: TYPE
296	        (el as any).domBelongToZr = true;
297	        this.el = el;
298	        const zr = this._zr = api.getZr();
299	
300	        const appendTo = opt.appendTo;
301	        const container: HTMLElement | null | undefined = appendTo && (
302	            isString(appendTo)
303	                ? document.querySelector(appendTo)
304	                : isDom(appendTo)
305	                    ? appendTo
306	                    : isFunction(appendTo) && appendTo(api.getDom())
307	        );
308	
309	        makeStyleCoord(this._styleCoord, zr, container, api.getWidth() / 2, api.getHeight() / 2);
310	
311	        (container || api.getDom()).appendChild(el);
312	
313	        this._api = api;
314	        this._container = container;
315	
316	        // FIXME
317	        // Is it needed to trigger zr event manually if
318	        // the browser do not support `pointer-events: none`.
319	
320	        const self = this;
321	        el.onmouseenter = function () {
322	            // clear the timeout in hideLater and keep showing tooltip
323	            if (self._enterable) {
324	                clearTimeout(self._hideTimeout);
325	                self._show = true;
326	            }
327	            self._inContent = true;
328	        };
329	        el.onmousemove = function (e) {
330	            e = e || (window as any).event;
331	            if (!self._enterable) {
332	                // `pointer-events: none` is set to tooltip content div
333	                // if `enterable` is set as `false`, and `el.onmousemove`
334	                // can not be triggered. But in browser that do not
335	                // support `pointer-events`, we need to do this:
336	                // Try trigger zrender event to avoid mouse
337	                // in and out shape too frequently
338	                const handler = zr.handler;
339	                const zrViewportRoot = zr.painter.getViewportRoot();
340	                normalizeEvent(zrViewportRoot, e as ZRRawEvent, true);
341	                handler.dispatch('mousemove', e);
342	            }
343	        };
344	        el.onmouseleave = function () {
345	            // set `_inContent` to `false` before `hideLater`
346	            self._inContent = false;
347	
348	            if (self._enterable) {
349	                if (self._show) {
350	                    self.hideLater(self._hideDelay);
351	                }
352	            }
353	        };
354	    }
355	
356	    /**
357	     * Update when tooltip is rendered
358	     */
359	    update(tooltipModel: Model<TooltipOption>) {
360	        if (!this.el) {
361	            // The tooltip content has been disposed, for example, when
362	            // `setOption` is called with the `notMerge` strategy, which makes
363	            // a new tooltip view (and content) replace the old one. Do nothing
364	            // rather than throw an error in that case. See #20433.
365	            return;
366	        }
367	
368	        // FIXME
369	        // Move this logic to ec main?
370	        if (!this._container) {
371	            const container = this._api.getDom();
372	            const position = getComputedStyle(container, 'position');
373	            const domStyle = container.style;
374	            if (domStyle.position !== 'absolute' && position !== 'absolute') {
375	                domStyle.position = 'relative';
376	            }
377	        }
378	
379	        // move tooltip if chart resized
380	        const alwaysShowContent = tooltipModel.get('alwaysShowContent');
381	        alwaysShowContent && this._moveIfResized();
382	
383	        // update alwaysShowContent
384	        this._alwaysShowContent = alwaysShowContent;
385	
386	        // update className
387	        this.el.className = tooltipModel.get('className') || '';
388	
389	        // Hide the tooltip
390	        // PENDING
391	        // this.hide();
392	    }
393	
394	    show(tooltipModel: Model<TooltipOption>, nearPointColor: ZRColor) {
395	        clearTimeout(this._hideTimeout);
396	        clearTimeout(this._longHideTimeout);
397	        const el = this.el;
398	        if (!el) {
399	            return;
400	        }
401	        const style = el.style;
402	        const styleCoord = this._styleCoord;
403	        if (!el.innerHTML) {
404	            style.display = 'none';
405	        }
406	        else {
407	            style.cssText = gCssText
408	                + assembleCssText(tooltipModel, !this._firstShow, this._longHide)
409	                // initial transform
410	                + assembleTransform(styleCoord[0], styleCoord[1], true)
411	                + `border-color:${convertToColorString(nearPointColor)};`
412	                + (tooltipModel.get('extraCssText') || '')
413	                // If mouse occasionally move over the tooltip, a mouseout event will be
414	                // triggered by canvas, and cause some unexpectable result like dragging
415	                // stop, "unfocusAdjacency". Here `pointer-events: none` is used to solve
416	                // it. Although it is not supported by IE8~IE10, fortunately it is a rare
417	                // scenario.
418	                + `;pointer-events:${this._enterable ? 'auto' : 'none'}`;
419	        }
420	
421	        this._show = true;
422	        this._firstShow = false;
423	        this._longHide = false;
424	    }
425	
426	    setContent(
427	        content: string | HTMLElement | HTMLElement[],
428	        markers: unknown,
429	        tooltipModel: Model<TooltipOption>,
430	        borderColor?: ZRColor,
431	        arrowPosition?: TooltipOption['position']
432	    ) {
433	        const el = this.el;
434	
435	        if (!el) {
436	            return;
437	        }
438	
439	        if (content == null) {
440	            el.innerHTML = '';
441	            return;
442	        }
443	
444	        let arrow = '';
445	        if (isString(arrowPosition) && tooltipModel.get('trigger') === 'item'
446	            && !shouldTooltipConfine(tooltipModel)) {
447	            arrow = assembleArrow(tooltipModel, borderColor, arrowPosition);
448	        }
449	        if (isString(content)) {
450	            el.innerHTML = content + arrow;
451	        }
452	        else if (content) {
453	            // Clear previous
