 898	        let align = tooltipModel.get('align');
 899	        let vAlign = tooltipModel.get('verticalAlign');
 900	        const rect = el && el.getBoundingRect().clone();
 901	        el && rect.applyTransform(el.transform);
 902	
 903	        if (isFunction(positionExpr)) {
 904	            // Callback of position can be an array or a string specify the position
 905	            positionExpr = positionExpr([x, y], params, content.el, rect, {
 906	                viewSize: [viewWidth, viewHeight],
 907	                contentSize: contentSize.slice() as [number, number]
 908	            });
