 910	
 911	        if (isArray(positionExpr)) {
 912	            x = parsePercent(positionExpr[0], viewWidth);
 913	            y = parsePercent(positionExpr[1], viewHeight);
 914	        }
 915	        else if (isObject(positionExpr)) {
 916	            const boxLayoutPosition = positionExpr as BoxLayoutOptionMixin;
