 24	
 25	type ThrottleFunction = (this: unknown, ...args: unknown[]) => void;
 26	export type ThrottleType = 'fixRate' | 'debounce';
 27	
 28	export interface ThrottleController {
 29	    clear(): void;
 30	    debounceNextCall(debounceDelay: number): void;
 31	};
 32	
 33	/**
 34	 * @public
 35	 * @param {(Function)} fn
 36	 * @param {number} [delay=0] Unit: ms.
 37	 * @param {boolean} [debounce=false]
 38	 *        true: If call interval less than `delay`, only the last call works.
 39	 *        false: If call interval less than `delay, call works on fixed rate.
 40	 * @return {(Function)} throttled fn.
 41	 */
 42	export function throttle<T extends ThrottleFunction>(
 43	    fn: T,
 44	    delay?: number,
 45	    debounce?: boolean
 46	): T & ThrottleController {
 47	
 48	    let currCall;
 49	    let lastCall = 0;
 50	    let lastExec = 0;
 51	    let timer: ReturnType<typeof setTimeout> = null;
 52	    let diff;
 53	    let scope: unknown;
 54	    let args: unknown[];
 55	    let debounceNextCall: number;
 56	
 57	    delay = delay || 0;
 58	
 59	    function exec(): void {
 60	        lastExec = (new Date()).getTime();
 61	        timer = null;
 62	        fn.apply(scope, args || []);
 63	    }
 64	
 65	    const cb = function (this: unknown, ...cbArgs: unknown[]): void {
 66	        currCall = (new Date()).getTime();
 67	        scope = this;
 68	        args = cbArgs;
 69	        const thisDelay = debounceNextCall || delay;
 70	        const thisDebounce = debounceNextCall || debounce;
 71	        debounceNextCall = null;
 72	        diff = currCall - (thisDebounce ? lastCall : lastExec) - thisDelay;
 73	
 74	        clearTimeout(timer);
 75	
 76	        // Here we should make sure that: the `exec` SHOULD NOT be called later
 77	        // than a new call of `cb`, that is, preserving the command order. Consider
 78	        // calculating "scale rate" when roaming as an example. When a call of `cb`
 79	        // happens, either the `exec` is called dierectly, or the call is delayed.
 80	        // But the delayed call should never be later than next call of `cb`. Under
 81	        // this assurance, we can simply update view state each time `dispatchAction`
 82	        // triggered by user roaming, but not need to add extra code to avoid the
 83	        // state being "rolled-back".
 84	        if (thisDebounce) {
 85	            timer = setTimeout(exec, thisDelay);
 86	        }
 87	        else {
 88	            if (diff >= 0) {
 89	                exec();
 90	            }
 91	            else {
 92	                timer = setTimeout(exec, -diff);
 93	            }
 94	        }
 95	
 96	        lastCall = currCall;
 97	    } as T & ThrottleController;
 98	
 99	    /**
100	     * Clear throttle.
101	     * @public
102	     */
103	    cb.clear = function (): void {
104	        if (timer) {
105	            clearTimeout(timer);
106	            timer = null;
107	        }
108	    };
109	
110	    /**
111	     * Enable debounce once.
112	     */
113	    cb.debounceNextCall = function (debounceDelay: number): void {
114	        debounceNextCall = debounceDelay;
115	    };
116	
117	    return cb;
118	}
