In TooltipView.dispose(), cancel everything the view scheduled:

    dispose(ecModel: GlobalModel, api: ExtensionAPI) {
        if (env.node || !api.getDom()) {
            return;
        }
        clearTimeout(this._showTimout);
        clearTimeout(this._refreshUpdateTimeout);
        this._showTimout = this._refreshUpdateTimeout = null;
        clear(this, '_updatePosition');
        this._tooltipContent.dispose();
        globalListener.unregister('itemTooltip', api);
    }

Keep the TooltipHTMLContent guards as belt-and-braces, but this is the fix that actually stops the disposed view from running.

Fix the timers in TooltipView.dispose (previous finding) AND make TooltipRichContent refuse to act after disposal, using a flag rather than a null `el` (since setContent creates `el`):

    private _disposed = false;
    ...
    setContent(...) {
        if (this._disposed) { return; }
        ...
    }
    show() {
        if (this._disposed || !this.el) { return; }
        ...
    }
    getSize() {
        if (!this.el) { return [0, 0]; }
        ...
    }
    moveTo(x, y) {
        if (this._disposed || !this.el) { return; }
        ...
    }
    _moveIfResized() {
        if (this._disposed || !this._zr) { return; }
        ...
    }
    hide() {
        clearTimeout(this._hideTimeout);
        ...
    }
    dispose() {
        this._disposed = true;
        clearTimeout(this._hideTimeout);
        this.el && this._zr.remove(this.el);
        this.el = null;
    }

